import{_ as a,c as n,a as p,o as i}from"./app-4Eu4JlZm.js";const t={};function r(l,e){return i(),n("div",null,e[0]||(e[0]=[p('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-11-10-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-11-10-资讯日报"><span>2026-11-10 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="openai与anthropic出1500万美元验卷" tabindex="-1"><a class="header-anchor" href="#openai与anthropic出1500万美元验卷"><span>OpenAI与Anthropic出1500万美元验卷</span></a></h3><p>OpenAI与Anthropic联合Simons基金会承诺1500万美元资金与资源，资助数学家检验AI成果。此前OpenAI放出722篇模型手稿，次日就因符号错误撤回3篇。</p><p>出资细节：两家各出500万美元，并额外提供算力与模型权限</p><p>争议起因：722篇手稿仅约42%经Lean形式化验证</p><p>资金用途：由Simons基金会管理，办公开研讨会拆解复杂证明<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0fc1a48b0548adced371418e85eaa4aa08398175d835efeabae9b376fdae5c6fcaf1730fd1c&amp;idx=2&amp;mid=2652741625&amp;sn=7e85097eb21e4e059d1e9f257aa0b18b" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="多agent协作平台multica支持自部署" tabindex="-1"><a class="header-anchor" href="#多agent协作平台multica支持自部署"><span>多Agent协作平台Multica支持自部署</span></a></h3><p>协作平台 Multica 支持人与多个 Agent 组队分派任务并共享上下文，提供 Web、桌面端以及 Docker Compose 本地自部署方案。</p><p>协作机制：支持指定 Agent 统筹调度并沉淀可复用技能</p><p>使用方式：提供在线版与桌面端，支持本地容器化部署<a href="https://mp.weixin.qq.com/s?__biz=Mzg3NjEzMjQzMw==&amp;chksm=cea40888601d766abc05284611055435fbf5e08962c3d4dd871204f71b8b515b8a80790d6374&amp;idx=2&amp;mid=2247511065&amp;sn=a1dcedc817f32fa1475f180015a1d3a4" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="claude-fable-5-2发布-降价且基准超opus" tabindex="-1"><a class="header-anchor" href="#claude-fable-5-2发布-降价且基准超opus"><span>Claude Fable 5.2发布：降价且基准超Opus</span></a></h3><p>Anthropic 发布面向高难度任务的 Claude Fable 5.2 与 Mythos 5.2。百万输入 token 降至 8 美元（降 20%）且输出提速 30%，基准全线压过 Opus 5.5，已向所有付费用户及云平台开放。</p><p>基准表现：FrontierSWE达69.9%，同等表现下单任务成本约Opus一半</p><p>跨界实操：自主推导两道黑洞物理开放题，并免改电路完成3款硬件设计</p><p>版本区隔：Fable面向大众且误拦少55%，Mythos专供受审机构主打网安<a href="https://mp.weixin.qq.com/s?__biz=MzA5MTIxNTY4MQ==&amp;chksm=86aaec030c5661fc3c4561414e3445ee26311cb13cca0b3992f54878b865490cec6bb1702d2f&amp;idx=1&amp;mid=2461161932&amp;sn=445e9f3e63d5f19446a711f537a92501" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="字节跳动发布生图模型-seedream-5-5" tabindex="-1"><a class="header-anchor" href="#字节跳动发布生图模型-seedream-5-5"><span>字节跳动发布生图模型 Seedream 5.5</span></a></h3><p>字节跳动上线生图模型 Seedream 5.5，支持连续编辑 100 轮图像且画面保真，已在豆包和即梦上线，2K 方图编辑成本约每张 0.28 元。</p><p>图层拆分：可将广告成图拆为独立图层，单改文字不重新出图</p><p>文字渲染：支持信息图海报中密集小字及中英日等多语言排布</p><p>素材融合：能直出透明底图，多图合成时统一光照与透视<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e98d781c14bfc27275b43c9973443695b89d74dc593bd821a1f1d1a95e9c88305913a519f7ab&amp;idx=1&amp;mid=2247942445&amp;sn=18eb40f983ce6f226d5e91685b655b10" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="智驾车企转向用世界模型做仿真验证" tabindex="-1"><a class="header-anchor" href="#智驾车企转向用世界模型做仿真验证"><span>智驾车企转向用世界模型做仿真验证</span></a></h3><p>随着各家架构趋同，智能驾驶行业对世界模型与 VLA 的宣传降温，研发重心转向利用仿真和闭环验证推进量产落地，重点防止局部优化在其他场景引发新的行车故障。</p><p>验证难点：端到端模型更新易牵一发动全身</p><p>应用方式：世界模型主攻低频场景推演与复测<a href="https://mp.weixin.qq.com/s?__biz=MzUyODY1NDE1NA==&amp;chksm=fbd6563841686359649cb0f021030c66ffb416241a2eab260ecfe89ed4f464316db47ed26f24&amp;idx=1&amp;mid=2247579043&amp;sn=de3f957c975f438de2a7458b5a33a8e7" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="开源社区整理5个claude设计工具" tabindex="-1"><a class="header-anchor" href="#开源社区整理5个claude设计工具"><span>开源社区整理5个Claude设计工具</span></a></h3><p>开源社区推出 5 个面向设计任务的 Claude 工具，涵盖界面生成、组件规格图绘制、获奖网站参考检索、设计系统搭建及品牌方案生成，均适配 Claude Code。</p><p>规格图：dimensional-drawing 自动标注间距与圆角</p><p>参考检索：Awwwards-mcp 免费抓取获奖网页截图</p><p>系统搭建：design.how 引导建立并迁移统一设计变量<a href="https://mp.weixin.qq.com/s?__biz=Mzg3NjEzMjQzMw==&amp;chksm=ce88217e85304727492595f57a2e6e7faf65b5dc5166a5c0851ef50f919a1f30d3ddd8a9283e&amp;idx=3&amp;mid=2247511065&amp;sn=ea6d3b175e72afeeeb6dd76c21bf9658" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="港科广开源驾驶视频模型-物理评测第一" tabindex="-1"><a class="header-anchor" href="#港科广开源驾驶视频模型-物理评测第一"><span>港科广开源驾驶视频模型，物理评测第一</span></a></h3><p>港科大（广州）团队开源视频框架 Motion Forcing，用单张照片加轨迹即可生成不穿模的行车视频；在 Waymo 实测中，其物理合理性与动作连贯性第一。</p><p>架构：分步生成轨迹点、深度结构图与最终彩色画面</p><p>训练：故意遮挡部分轨迹，让模型自主推断惯性与遮挡</p><p>可用性：代码、模型权重与网页交互 Demo 均已开源<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9b4ae61863aef2020603861565433dec4ae86ef52ba16818aa1facf2a3495140e23fb619882&amp;idx=3&amp;mid=2247942445&amp;sn=daa8c5e19b4475029e89910f836ad72a" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',41)]))}const s=a(t,[["render",r]]),d=JSON.parse('{"path":"/posts/2026-11-10.html","title":"AI日报：OpenAI与Anthropic出1500万美元验卷; 多Agent协作平台Multica支持自部署; Claude Fable 5.2发布：降价且基准超Opus","lang":"zh-CN","frontmatter":{"date":"2026-11-10T00:00:00.000Z","title":"AI日报：OpenAI与Anthropic出1500万美元验卷; 多Agent协作平台Multica支持自部署; Claude Fable 5.2发布：降价且基准超Opus"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"OpenAI与Anthropic出1500万美元验卷","slug":"openai与anthropic出1500万美元验卷","link":"#openai与anthropic出1500万美元验卷","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"多Agent协作平台Multica支持自部署","slug":"多agent协作平台multica支持自部署","link":"#多agent协作平台multica支持自部署","children":[]},{"level":3,"title":"Claude Fable 5.2发布：降价且基准超Opus","slug":"claude-fable-5-2发布-降价且基准超opus","link":"#claude-fable-5-2发布-降价且基准超opus","children":[]},{"level":3,"title":"字节跳动发布生图模型 Seedream 5.5","slug":"字节跳动发布生图模型-seedream-5-5","link":"#字节跳动发布生图模型-seedream-5-5","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"智驾车企转向用世界模型做仿真验证","slug":"智驾车企转向用世界模型做仿真验证","link":"#智驾车企转向用世界模型做仿真验证","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"开源社区整理5个Claude设计工具","slug":"开源社区整理5个claude设计工具","link":"#开源社区整理5个claude设计工具","children":[]},{"level":3,"title":"港科广开源驾驶视频模型，物理评测第一","slug":"港科广开源驾驶视频模型-物理评测第一","link":"#港科广开源驾驶视频模型-物理评测第一","children":[]}]}],"git":{"updatedTime":1794397207000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"aae64342e48c6dafeb6f73a344aac13e9e2e1db6","time":1794397207000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-11-11T11:40:07.408Z"}]},"filePathRelative":"posts/2026-11-10.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-11-10 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>OpenAI与Anthropic出1500万美元验卷</h3>\\n<p>OpenAI与Anthropic联合Simons基金会承诺1500万美元资金与资源，资助数学家检验AI成果。此前OpenAI放出722篇模型手稿，次日就因符号错误撤回3篇。</p>"}');export{s as comp,d as data};
